INSERT INTO "heritage_buildings" ("id", "name", "address", "function", "ownership", "land_area_m2", "floor_area_m2", "heritage_rank", "heritage_rank_year", "heritage_style_type", "managing_unit", "overall_structure_description", "cultural_historical_value", "built_period", "restoration_note", "gallery_media_ids", "created_at", "updated_at", "village_id")
VALUES
  ('44000000-0000-0000-0000-000000000001', 'Đình làng Ước Lễ', 'làng Ước Lễ, xã Dân Hòa, Hà Nội', 'Đình làng', NULL, 2500, NULL, 'di tích cấp quốc gia', 2008, 'Kiến trúc nghệ thuật', NULL, 'Đình làng là tổ hợp kiến trúc bao gồm Nghi môn, Tiền tế, Đại bái, Phương đình, Hậu cung và Tả hữu mạc. Trước 2 bên cửa Hậu cung là ngựa tế đỏ bên trái và ngựa tế trắng bên phải', 'Đình Ước Lễ thờ Tể tướng Lữ Gia làm thành hoàng làng, vị anh hùng trong cuộc chiến tranh chống quân Nam Hán xâm lược, với sự tích khi ngài chống quân Nam Hán đã bị chém đầu vẫn phi ngựa chạy về đến trước cổng làng Ước Lễ thì hóa. Tể tướng Lữ gia hy sinh ngày 12/9 âm lịch năm Canh ngọ (111 TCN). Hiện có trên 70 làng tôn Ngài là Đức Thành Hoàng làng (theo Tóm tắt lịch sử Việt Nam)', 'TK 17', NULL, NULL, '2026-09-21T02:54:19.499Z', '2026-09-21T07:18:35.222Z', '00000000-0000-0000-0000-000000000001'),
  ('44000000-0000-0000-0000-000000000002', 'Chùa Sổ', 'làng Ước Lễ, xã Dân Hòa, Hà Nội', 'Chùa', NULL, 5000, NULL, 'di tích cấp quốc gia', 1986, 'Kiến trúc nghệ thuật', NULL, 'Chùa xây kiểu “Nội công ngoại quốc” với hai hành lang 26 gian, nối hai đầu tiền đường, cùng nhà hậu phía sau bao lấy tòa thượng điện.Kiến trúc “Chồng giường, giá chiêng, con nhị” với kết câu trên là hai xà ngân, đặt trên đầu hai cột con và tất cả đặt trên quá giang đội toàn bộ mái. Toàn bộ tượng trong chùa có tất cả 25 pho được làm vào thế kỷ 17 và 18, có giá trị lịch sử lớn.', 'Chùa Sổ hay còn gọi là Hội Linh quán, mang tinh thần tam giáo đồng nguyên. Ngoài hai bức đại tự "Hội Linh Quán" và "Đại La thiên" những phạm trù trong Đạo giáo, còn có bức "Từ Vân Pháp Vũ" ở thượng điện thể hiện sự giao hòa tín ngưỡng dân gian thờ bà Pháp Vũ của người Việt Nam. Tại văn bia Quán Hội Linh của chùa Sổ có ghi việc tu sửa quán Hội Linh, tô tạo tượng phạt, đúc chuông cùng bài tựa: “... Xã Ước Lễ huyện Thanh Oai phủ Ứng Thiên có quan Hội Linh nổi tiếng ở nước Nam ta. Bên trái có thanh long dẫn dòng đỗ đạt, sông Tô uốn quanh; bên phải có bạch hổ bày núi bút nghiên, bảng vàng chói lọi. Phía trước Chu Tước ôm ấp chính dòng nước, cuồn cuộn đổ về nguồn. Đằng sau huyền vũ thật chênh vênh, núi cao hơn đất. Bốn bề chung đúc khí thiêng, người tài vật quý, chư Phật thảy đều linh ứng, phúc đến lộc về.”
Chùa Sổ là một trong những ngôi chùa hiếm hoi còn giữ được dấu tích nền móng thời Mạc (1527), hệ thống di vật ở chùa cho thấy có sự giao thoa phát triển đặc sắc của điêu khắc, kiến trúc Mạc, Lê Trung Hưng và Nguyễn. Về kiến trúc, chùa kết cấu theo kiểu nội công - ngoại quốc. Từ cổng chùa vào là tam quan được xây kiểu chồng diêm, hai tầng tám mái, lợp ngói vảy cá. Giữa tam quan có quả chuông đồng lớn đề bốn chữ: “Quan Chung Linh tự”. Xung quanh chùa được xây thêm giếng nước và trồng nhiều cây xanh góp phần làm cho không gian thêm thanh bình êm ả.', 'TK 16', NULL, NULL, '2026-09-21T02:54:19.499Z', '2026-09-21T07:18:35.222Z', '00000000-0000-0000-0000-000000000001'),
  ('44000000-0000-0000-0000-000000000003', 'Nhà cụ Khả (3)', 'làng Ước Lễ, xã Dân Hòa, Hà Nội', 'nhà thờ họ', 'nhà cụ Khả', 415.5, 137.26, NULL, NULL, 'Kiến trúc nghệ thuật', NULL, 'Nhà 5 gian', 'Ngôi nhà truyền thống vùng đồng bằng Bắc Bộ với 5 gian gồm nhà chính phục vụ thờ cúng, tiếp khách; nhà phụ phục vụ sinh hoạt gia đình; khu bếp phục vụ nấu nướng; sân là không gian sinh hoạt chung; bể nước đảm bảo nhu cầu sử dụng nước và tiểu cảnh góp phần nâng cao giá trị cảnh quan.', NULL, NULL, NULL, '2026-09-21T02:54:19.499Z', '2026-09-21T07:33:19.869Z', '00000000-0000-0000-0000-000000000001'),
  ('44000000-0000-0000-0000-000000000004', 'Nhà bà Bào (4)', 'Làng Ước Lễ, xã Dân Hòa, Hà Nội', 'Nhà ở', 'Nhà bà Bào', 489.25, 243.14, NULL, NULL, 'Kiến trúc', NULL, 'Nhà 5 gian', 'Ngôi nhà 5 gian truyền thống vùng đồng bằng Bắc Bộ còn giữ được các nét kiến trúc bản địa', '1988', NULL, NULL, '2026-09-21T02:54:19.499Z', '2026-09-21T07:18:35.222Z', '00000000-0000-0000-0000-000000000001'),
  ('3ee3bd85-6227-4c96-ba05-ff8b2b74034d', 'nhà ông Mão', 'làng Cự Đà, xã Bình Minh, Hà Nội', 'Nhà ở', NULL, 204.61, 119.34, NULL, NULL, 'Kiến trúc nghệ thuật', NULL, 'Nhà 3 gian', NULL, NULL, NULL, NULL, '2026-09-21T07:18:17.766Z', '2026-09-21T07:18:17.766Z', '01000000-0000-0000-0000-000000000001'),
  ('414cdd05-ffeb-4ea2-b5f4-3c4caa9b0c02', 'Chùa Cự Đà _ Linh Minh Tự', 'làng Cự Đà, xã Bình Minh, Hà Nội', 'Chùa', NULL, NULL, NULL, 'cấp quốc gia', 2000, 'lịch sử văn hóa', NULL, 'ba gian hai chái. Chùa có một cổng phụ phía Tây mở ra bãi đất liền với cánh đồng làng. Cổng phụ phía Đông ăn thông với lối đi chính về phía cầu đường sắt. Cổng lớn của chùa là một tam quan hẹp, mặt quay hướng Nam nhìn qua hai cây muỗm to ra sông Nhuệ.', 'Chùa Cự Đà hay còn gọi là Linh Minh tự. Theo văn bia ghi lại, Linh Minh tự nằm ở phía Đông khu dân cư đô hội, phía Tây long phượng chầu về, bên phải là miếu thờ Thành Hoàng, bên trái là từ đường nhà họ Đinh, trước mặt là dòng sông Nhuệ uốn quanh, xứng đáng chốn danh lam trong vùng.', 'Không ai còn nhớ rõ - thời điểm trùng tu lần đầu tiên vào mùa xuân niên hiệu Chính Hòa thứ 16 thời Hậu Lê (1695)', NULL, NULL, '2026-09-21T07:18:17.766Z', '2026-09-21T07:18:17.766Z', '01000000-0000-0000-0000-000000000001'),
  ('98dbb779-b90c-469b-bc18-8179a8158231', 'Đình làng Cự Đà', 'làng Cự Đà, xã Bình Minh, Hà Nội', 'Đình làng', NULL, 553.13, 276.78, NULL, NULL, NULL, NULL, 'Đình có 2 phần cơ bản là nhà tiền tế có gian giữa thờ chính, tả ban và hữu ban thờ cận thần, phía trong là hậu cung.', 'Đình gắn với truyền thuyết đây là nơi tuyển chọn binh lính trong thời kỳ dẹp loạn 12 sứ quân của vị tướng nhà Đinh. Hàng năm vào ngày 14 tháng giêng âm lịch có lễ hội Đại kỳ phúc tiến hành lễ rước Thành Hoàng Thông Phả Độ Đại vương. Cứ 5 năm 1 lần trong ngày hội lớn, tục đấu vật được biểu diễn lại ngay tại sân đình', NULL, NULL, NULL, '2026-09-21T07:18:17.766Z', '2026-09-21T07:18:17.766Z', '01000000-0000-0000-0000-000000000001'),
  ('bf94d200-fd5c-46ea-a1fb-2cb52eb4797c', 'Nhà ông Vũ Ngọc Giao', 'làng Cự Đà, xã Bình Minh, Hà Nội', 'nhà ở', 'Ông Vũ Ngọc Giao', 689.44, 493.84, NULL, NULL, 'Kiến trúc nghệ thuật', NULL, 'nhà3 gian 2 chái', NULL, NULL, NULL, NULL, '2026-09-21T07:18:17.766Z', '2026-09-21T07:18:17.766Z', '01000000-0000-0000-0000-000000000001'),
  ('2113eaa5-1727-4f3c-9f78-f2a426fda3d9', 'Đình Hạ Thái còn có tên gọi là Đình Bà Lạy', 'Thôn Hạ Thái, xã Duyên Thái, huyện Thường Tín, TP. Hà Nội ( Xã Hồng Vân)', 'Đình làng. Công trình tín ngưỡng thờ Thành hoàng làng', NULL, NULL, NULL, 'Di tích Quốc gia', 2017, 'Di tích kiến trúc nghệ thuật', NULL, 'Khuôn viên Đình bao gồm: Đình chính hình chữ Công, nối thêm 2 nhà hành làng phía sau.  Phía trước là sân đình, sân có 3 nghi môn mỗi nghi môn có 2 trụ biểu, chính giữa mặt trước là 1 nghi môn và hai bên sân là 2 nghi môn kết nối với các đường làng. Phía trước Đình là giếng làng , tiếp đến là nhà Bia giữa hồ. Bia ghi tóm tắt lại lịch sử xây dựng đền cũng như các vị nhân thần được thờ trong Đình.', 'Nơi thờ hai vị Thành hoàng làng:  Thờ vọng quan võ thời Lê là Bùi Sĩ Lượng và bà Đinh Thị Trạch (bà Lạy). Gắn liền với lễ hội làng diễn ra từ ngày 9 đến 11/11 âm lịch hàng năm. Đình thờ chính là bà Đinh Thị Lạy. Theo văn bia: " Xưa kia vùng này vốn hoang vu, rậm rạp. Có con hổ dữ hoành hoành. Bà Lạy đã khấn trời đất và xin từ nộp mình cho hổ dữ, từ đó về sau hổ không còn xuất hiện nữa...Bà là người đức sáng, thuần nhã thực xứng đáng là đức Huy Đôn Ý Đại Vương. Đạo theo đạo trời, đức hợp với đất. Giúp nước giữ vẻ thanh bình, giữ cho dân yên, mở mang sáng tốt. Là bậc đại vương ý sáng, đức thuần, đôn hậu, chu toàn, minh triết, ôn hòa cung kính. Bao nhiêu lần bà đã hiển linh vượt lên cả những gì đã được tôn sùng và phong cấp. Xin ghi chép lại nơi điển sách để lưu giữ mãi muôn đời tự vương tiến phong, ngày 26/7/1783 ( năm Cảnh Hưng thứ 44) "', 'Khởi dựng đình vào năm 1780. Trùng tu gian ống muống năm 1994, thay thế cột gỗ bằng cột gạch và tường gạch thông gió. Năm 2026 sẽ được hạ giải và trùng tu lớn, thay thế những cấu kiện gỗ bị hư hỏng ( tại thời điểm khảo sát vào tháng 7/2026 thì chưa hạ giải.)', NULL, NULL, '2026-09-21T07:18:32.033Z', '2026-09-21T07:18:32.033Z', 'fdd98e46-3b65-490d-aadc-dbb90eab321d'),
  ('5b72fa35-638b-44c6-ab02-3947ba5a6102', 'Nhà cổ', 'Số 14 ngõ 12 Mỹ Lộc, thôn Hạ Thái , xã Hồng Vân, Hà Nội', 'Nhà ở', 'Bà Đỗ Thị Dịp', 512, NULL, 'Chưa', NULL, NULL, NULL, 'Trong khuôn viên có 2 ngôi nhà trong đó có 1 nhà cổ xây năm 1943, Nhà 5 gian (kí hiệu số 3 trên TMB).', 'Ngôi nhà được xây năm 1943, cổng xây 1946, có trùng tu một vài bộ phận và nâng nền vào năm 2016. Tuy chưa được xếp hạng di tích, nhưng ngôi nhà cũng có tuổi đời hơn 80 năm, còn gần như nguyên vẹn phong cách kiến trúc cuối thời Nguyễn. Do tốp thợ Nam Định thi công trong 2 năm.', '1943 (Chủ nhà cung cấp)', NULL, NULL, '2026-09-21T07:18:32.033Z', '2026-09-21T07:18:32.033Z', 'fdd98e46-3b65-490d-aadc-dbb90eab321d'),
  ('28dc7a86-a741-4fd7-9407-454b6af79bb4', 'nhà ông Lê Văn Trường', 'số 5 ngõ nghè thôn quang trung xã Phương Trung huyện Thanh Oai tp Hà Nội', 'nhà ở', 'ông Lê Văn Trung', 701, NULL, 'không có', NULL, 'không có', NULL, 'nhà 3 gian 2 chái', 'Ngôi nhà cổ có giá trị lâu đời, được truyền thừa qua nhiều đời, vẫn giữ nguyên được lối kiến trúc cổ đặc trưng vùng Đồng bằng Bắc Bộ và tính chất gia đình danh giá thời xưa', NULL, NULL, NULL, '2026-09-21T07:18:32.871Z', '2026-09-21T07:18:32.871Z', '09ee09b0-41f2-429c-a515-0cd2592edc44'),
  ('821ce853-ea6d-4a82-a68f-c9f22e4a2014', 'Đền Thượng', 'Thôn Tân Quang, xã Thanh Oai, thành phố Hà Nội', 'Đền thờ cúng đức thánh Phùng Hưng', 'của nhân dân', NULL, NULL, 'Cấp quốc gia', 1989, 'di tích lịch sử', NULL, 'Chùa được xây dựng theo hình Đinh, 8 mái, tiền đường 5 gian, hậu cung 2 gian, nhà tổ có nhiều pho tượng cổ, sân chùa có cây đa cổ thụ hơn 100 tuổi.', NULL, 'năm 1894', NULL, NULL, '2026-09-21T07:18:32.871Z', '2026-09-21T07:18:32.871Z', '09ee09b0-41f2-429c-a515-0cd2592edc44'),
  ('e92783f4-ea38-4375-9555-6751b3ac9129', 'đình làng chuông', 'làng Chuông, xã Phương Trung, huyện Thanh Oai, Hà Nội.', 'đình', 'nhân dân', 481.44187, 1500, 'Cấp quốc gia', 1990, 'di tích lịch sử', NULL, 'Chùa được xây dựng theo hình Đinh, 8 mái, tiền đường 5 gian, hậu cung 2 gian, nhà tổ có nhiều pho tượng cổ, sân chùa có cây đa cổ thụ hơn 100 tuổi.', '- Đình thờ Lục vị Thành hoàng làng, bao gồm 2 vị thiên thần (Đức Thiên thần Địa kỳ và Thổ kỳ) và 4 vị nhân thần là Bố Cái Đại vương Phùng Hưng, Đức Đỗ Huệ, Thánh mẫu Tiên Dung và danh tướng Nguyễn Xí. Đây là nơi tri ân những nhân vật lịch sử có công mở đất, bảo vệ quê hương và là điểm tựa tinh thần của người dân
- mang đậm dấu ấn kiến trúc đình chùa truyền thống của vùng Đồng bằng Bắc Bộ, gắn liền với các mảng chạm khắc gỗ tinh xảo, thể hiện tay nghề thủ công đỉnh cao của các nghệ nhân xưa', '1894', NULL, NULL, '2026-09-21T07:18:32.871Z', '2026-09-21T07:18:32.871Z', '09ee09b0-41f2-429c-a515-0cd2592edc44'),
