  ('909dd7d6-0c65-4f11-bedf-c6fecd4f9198', 'Nhà thờ họ Trần', 'Số  11 thôn Cựu', 'Nhà thờ họ', 'Dòng họ Trần - Làng Cựu', 135, 50, 'Không có', NULL, 'Không có', 'Họ trần', 'Gian thờ chính có 3 gian theo nếp cổ, có nhà phụ phía sau và bể nước ở sân', 'là nơi thờ cúng của cư dân họ trần nói riêng dân làng nói chung', '1926', NULL, NULL, '2026-09-21T07:18:33.530Z', '2026-09-21T07:18:33.530Z', 'c33319de-4845-41bf-94c1-3fa501e5e867'),
