  ('309af77b-1057-4d24-90ea-c37e69be4979', 'Nhà nghệ nhân Hoàng Hạnh', 'Thôn Phú Hữu, xã Phú Hữu', 'Nhà ở', 'Hoàng Hạnh', NULL, NULL, 'Không rõ', NULL, 'Không rõ', 'Không rõ', 'Nhà cũ 3 gian 2 chái', NULL, 'Trước 1954', NULL, NULL, '2026-09-21T07:18:34.352Z', '2026-09-21T07:18:34.352Z', '8216fe86-f66d-4b19-904b-cbdee0bf1eba'),
